from pathlib import Path
import re, html
base = Path(__file__).parent
source = (base / "mezuzah.he.md").read_text(encoding="utf-8")
def inline(s):
    s=html.escape(s)
    s=re.sub(r"\*\*(.*?)\*\*",r"<strong>\1</strong>",s)
    return re.sub(r"\[([^\]]+)\]\(([^)]+)\)",r'<a href="\2">\1</a>',s)
sections=[]
for index, block in enumerate(source.split("\n## ")[1:]):
    title, body=block.split("\n",1)
    parts=[]
    listing=False
    for line in body.strip().splitlines():
        if not line.strip(): continue
        ordered=re.match(r"^\d+\. (.*)",line)
        if ordered:
            if not listing: parts.append('<ol class="steps">'); listing=True
            parts.append("<li>"+inline(ordered[1])+"</li>")
        else:
            if listing: parts.append("</ol>"); listing=False
            if line.startswith("- "): parts.append('<p class="catalog-link">'+inline(line[2:])+"</p>")
            elif line.startswith("**") and "?" in line:
                match=re.match(r"\*\*(.*?)\*\*\s*(.*)",line)
                parts.append("<details><summary>"+inline(match[1])+"</summary><p>"+inline(match[2])+"</p></details>")
            else: parts.append("<p>"+inline(line)+"</p>")
    if listing: parts.append("</ol>")
    sections.append(f'<section id="section-{index}"><h2>{html.escape(title)}</h2>{"".join(parts)}</section>')
wa=re.search(r"\[התייעצות ב-WhatsApp\]\(([^)]+)\)",source)[1]
